let wbBusinessTab={cats:'全部',rescue:'全部',foster:'全部',adoption:'推进中',sterilization:'待绝育'},wbSaleChannel='线上',wbFinanceTab='明细',wbHistoryAdoptions=false,wbFormLines=1,wbLedgerDirection='全部',wbMonthlyCategory='全部',wbAdoptionIntent='全部',wbFollowupTab='待回访';
const wbTitle={rescue:'救助',foster:'寄养',adoption:'领养',sterilization:'绝育',cats:'猫咪档案'};
const wbDataName={...names,sales:'文创售卖',movements:'物资流水'};
const wbListPages=new Map();let wbListPageInfo=null,wbRemoteList=null;
function wbPageKey(){return JSON.stringify([page,query,month,wbBusinessTab[page],inventoryGroup,inventoryView,wbSaleChannel,wbFinanceTab,wbLedgerDirection,wbMonthlyCategory,wbHistoryAdoptions,wbAdoptionIntent,wbFollowupTab]);}
function wbListRequest(){
 const key=wbPageKey(),collection=page==='inventory'?(inventoryView==='stock'?'inventory':inventoryView):page;
 return {key,collection,params:{q:query,month,page:wbListPages.get(key)||1,pageSize:page==='cats'?9:page==='inventory'&&inventoryView==='stock'?6:10,tab:[...businessTypes,'cats'].includes(page)?wbBusinessTab[page]:page==='finance'?wbFinanceTab:'',intent:wbAdoptionIntent,followup:wbFollowupTab,history:wbHistoryAdoptions?'1':'0',direction:wbLedgerDirection,category:wbMonthlyCategory,group:inventoryGroup,channel:wbSaleChannel,grouped:page==='inventory'&&inventoryView==='stock'?'1':'0',target:wbHomeTarget?.id||''}};
}
function wbPageRows(rows,size=10){if(wbRemoteList){wbListPageInfo={key:wbPageKey(),current:wbRemoteList.page,pages:wbRemoteList.pages,size:wbRemoteList.pageSize,total:wbRemoteList.total};wbListPages.set(wbPageKey(),wbRemoteList.page);return rows;}const key=wbPageKey(),pages=Math.max(1,Math.ceil(rows.length/size));let current=Math.max(1,Math.min(pages,wbListPages.get(key)||1));if(wbHomeTarget){const i=rows.findIndex(r=>Array.isArray(r)?r.some(i=>i.id===wbHomeTarget.id):r.id===wbHomeTarget.id);if(i>=0)current=Math.floor(i/size)+1;}wbListPages.set(key,current);wbListPageInfo={key,current,pages,size,total:rows.length};return rows.slice((current-1)*size,current*size);}
function wbPagination(){const p=wbListPageInfo;if(!p||p.pages<=1)return '';const nums=[...new Set([1,...Array.from({length:5},(_,i)=>p.current-2+i).filter(n=>n>1&&n<p.pages),p.pages])];return `<nav class="list-pagination" aria-label="记录分页"><span>共 ${p.total} 条 · 每页 ${p.size} 条</span><div>${wbButton('上一页','page',`data-page-number="${p.current-1}" ${p.current===1?'disabled':''}`)}${nums.map((n,i)=>`${i&&n>nums[i-1]+1?'<span class="page-ellipsis">…</span>':''}<button type="button" class="page-number ${n===p.current?'current':''}" data-action="wb-page" data-page-number="${n}" aria-label="第 ${n} 页" ${n===p.current?'aria-current="page"':''}>${n}</button>`).join('')}${wbButton('下一页','page',`data-page-number="${p.current+1}" ${p.current===p.pages?'disabled':''}`)}</div></nav>`;}
function wbMonthlyCountText(rows){const labels={'救助管理':'救助','寄养管理':'寄养','绝育管理':'绝育','领养管理':'领养'},groups=new Map();for(const r of rows){if(!groups.has(r.category))groups.set(r.category,[]);groups.get(r.category).push(r);}return [...groups].map(([category,records])=>labels[category]?labels[category]+' '+new Set(records.map(r=>r.cat&&r.cat!=='公共事项'?wbFindCat(r.cat)?.id||wbCatNameKey(r.cat):r.id)).size+' 只':category+' '+records.length+' 项');}
function wbCatDescription(c){return `<section class="cat-description"><div class="section-caption"><h3>猫咪描述</h3>${wbButton(c.description?'编辑描述':'添加描述','cat-description',`data-id="${c.id}"`)}</div><p class="${c.description?'':'description-empty'}">${esc(c.description||'记录它的性格、习惯和喜欢的事物…')}</p></section>`;}
function wbEditCatDescription(id){const c=find('cats',id);if(!c||c.deletedAt)return;showModal(c.name+' · 猫咪描述',field('猫咪描述','description',c.description||'','textarea'),v=>{if(!wbSaveCatDescription(id,v.description))return false;wbCatProfile(find('cats',id));return false;},'保存描述');}
function wbButton(text,action,attrs='',primary=false){return button(text,'wb-'+action,attrs,primary?'primary':'secondary')}
function wbTop(title,subtitle,addLabel){return `<div class="page-heading"><div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${addLabel?wbButton(icon('plus')+addLabel,'add','','true'):''}</div>`}
function wbTable(heads,rows){return `<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(cells=>`<tr>${cells.map((c,i)=>`<td data-label="${esc(heads[i])}">${heads[i]==='操作'?`<div class="table-actions">${c}</div>`:c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}" class="empty">这里暂时没有记录。</td></tr>`}</tbody></table></div>`}
function wbMenu(items){return `<span class="inline-actions">${items.join('')}</span>`}
function wbRowActions(type,r){return '<div class="record-actions">'+wbButton('查看','detail',`data-type="${type}" data-id="${r.id}"`)+wbMenu([wbButton('编辑','edit',`data-type="${type}" data-id="${r.id}"`),button('删除','delete',`data-type="${type}" data-id="${r.id}"`)])+'</div>'}
function wbMonth(){return `<label class="month-field">月份<input id="month" type="month" value="${month}" aria-label="筛选月份" required></label>`}
function wbFilters(showMonth=false){return `<div class="filters">${showMonth?wbMonth():''}<input class="search" id="search" placeholder="搜索猫咪、物资或记录…" aria-label="搜索记录" value="${esc(query)}"><span class="record-count" id="count"></span></div>`}
function wbSubnav(){return tabs([['cats','档案'],['rescue','救助'],['foster','寄养'],['adoption','领养'],['sterilization','绝育']],page,'data-wb-route')}
function wbRender(){
 page=names[location.hash.slice(1)]?location.hash.slice(1):'overview';
 wbPrepareHomeTarget();
 const catSection=[...businessTypes,'cats'].includes(page),section=catSection?'猫咪事务':page==='overview'?'首页':names[page];
 $('#crumb').textContent=section+(catSection?' / '+wbTitle[page]:'');
 $('#nav').innerHTML=[['overview','首页','overview'],['sterilization','猫咪事务','cats'],['inventory','物资管理','inventory'],['finance','财务管理','finance'],['monthly','本月工作','monthly']].map(([key,title,ico])=>`<a class="nav-item ${(catSection&&key==='sterilization'||page===key)?'active':''}" href="#${key}">${icon(ico)}${title}</a>`).join('');
 $('#main').className=page==='overview'?'home-page':'';
 $('#main').innerHTML=page==='overview'?wbHome():catSection?wbCatPage():page==='inventory'?wbInventoryPage():page==='finance'?wbFinancePage():page==='monthly'?wbMonthlyPage():historyPage();
 if(page!=='overview'&&page!=='history')wbRefresh();
 wbLoadImages();wbStartStories();wbFocusHomeTarget();
}

let wbHomeTarget=null;
function wbHomeJump(type,id){const r=find(type,id);if(!r||r.deletedAt)return wbError('这条记录已不可用');const route=['sales','movements'].includes(type)?'inventory':type;wbHomeTarget={type,id,route};if(location.hash==='#'+route)wbRender();else location.hash='#'+route;}
function wbPrepareHomeTarget(){if(!wbHomeTarget||wbHomeTarget.route!==page)return;const r=find(wbHomeTarget.type,wbHomeTarget.id);if(!r){wbHomeTarget=null;return;}query=wbHomeTarget.type==='movements'?r.itemName||'':r.cat||r.name||r.title||'';filter='';if(businessTypes.includes(page)){wbBusinessTab[page]=page==='adoption'?(r.status==='已领养'?'已领养':'推进中'):r.status;if(page==='adoption'){wbFollowupTab=wbFollowup(r).label==='已完成'?'已回访':'待回访';wbAdoptionIntent=r.status==='已领养'?'全部':r.status;}if(r.releaseDate)month=r.releaseDate.slice(0,7);}if(page==='inventory'){inventoryGroup=wbHomeTarget.type==='sales'?'文创':r.group;inventoryView=wbHomeTarget.type==='sales'?'sales':'stock';if(wbHomeTarget.type==='sales')wbSaleChannel=r.channel;if(wbHomeTarget.type==='movements'){inventoryGroup=find('inventory',r.itemId)?.group||'日常';inventoryView='movements';}}}
function wbFocusHomeTarget(){if(!wbHomeTarget||wbHomeTarget.route!==page)return;const target=wbHomeTarget;const action=document.querySelector('#wb-list [data-id="'+target.id+'"]');if(!action||typeof action.closest!=='function')return;wbHomeTarget=null;const group=action.closest('details');if(group)group.open=true;const record=action.closest('tr')||group||action;record.classList.add('jump-highlight');record.scrollIntoView({block:'nearest',behavior:'smooth'});}
function wbAddSelectSearch(panel,kind='关联业务'){const holder=document.createElement('div');holder.className='wb-select-search';const input=document.createElement('input');input.type='search';input.placeholder=kind==='猫咪'?'搜索猫名、分类或地点…':'搜索猫咪、业务或记录…';input.setAttribute('aria-label','搜索'+kind);input.autocomplete='off';const empty=document.createElement('p');empty.className='wb-select-no-results';empty.textContent='没有找到匹配业务';empty.hidden=true;holder.append(input);panel.prepend(holder);panel.append(empty);input.addEventListener('input',()=>{const key=input.value.trim().toLowerCase().replace(/\s+/g,'');let count=0;for(const option of panel.querySelectorAll('.wb-select-option')){const match=option.textContent.toLowerCase().replace(/\s+/g,'').includes(key);option.hidden=!match;if(match)count++;}empty.hidden=count>0;});}
function wbTask(type,id,title,description,actionText='查看',action='detail',attrs=''){return {type,id,title,description,actionText,action,attrs}}
function wbTasks(){
 const tasks=[];
 for(const r of active('rescue'))if(r.status!=='已结束')tasks.push(wbTask('rescue',r.id,(r.cat||r.place)+' · '+r.status,r.nextStep||r.issue));
 for(const r of active('sterilization'))if(r.status==='住院中')tasks.push(wbTask('sterilization',r.id,r.cat+' · 住院中',(r.surgeryDate?'手术 '+r.surgeryDate+'；':'')+(r.hospital||'医院待补充')));
 for(const r of active('foster'))if(r.status==='待安置')tasks.push(wbTask('foster',r.id,(r.cat||'未建档猫咪')+' · 等待安置',r.nextStep||'地点与照护人待确认'));
 for(const s of active('sales'))if(s.channel==='线上'&&!s.cancelledAt&&!s.deliveredDate)tasks.push(wbTask('sales',s.id,s.title+' · '+(s.delivery==='自提'?'待自提':'未发货'),s.lines.map(l=>l.name+' × '+l.quantity).join('、'),'登记'+(s.delivery==='自提'?'已自提':'发货'),'deliver'));
 for(const a of active('adoption')){const follow=wbFollowup(a);if(follow.due)tasks.push(wbTask('adoption',a.id,a.cat+' · 待回访','本次应回访 '+follow.next,'记录回访','followup'));}
 for(const b of active('finance'))if(b.status==='待确认'||b.status==='待审核'||b.status==='审核通过'||b.status==='待付款'||b.refundReview)tasks.push(wbTask('finance',b.id,b.title+' · '+(b.refundReview?'取消收入需人工核对':b.status),money(b.amountCents),'查看账目','detail'));
 return tasks;
}
function wbHome(){const tasks=wbTasks().filter(t=>t.type!=='finance'),groups=[['猫咪事务',tasks.filter(t=>businessTypes.includes(t.type))],['物资与交付',[...tasks.filter(t=>t.type==='sales'),...active('inventory').map(i=>wbTask('inventory',i.id,i.name+' · '+i.place,'在库 '+i.qty+' '+i.unit+(i.group==='文创'?' · 可售 '+wbAvailable(data,i.id):''),'跳转','item'))]]];
 return `<div class="home-heading"><h1>待处理事项</h1><div class="home-heading-meta"><strong>${today}<span>·</span>${tasks.length} 项待处理</strong><a href="#monthly">查看本月完成工作 →</a></div></div><div class="queue-grid">${groups.map(([title,items])=>`<section class="panel queue"><div class="panel-head"><h2>${title}</h2><span class="count-chip">${items.length}</span></div><div class="queue-scroll" tabindex="0" role="region" aria-label="${title}待处理列表">${items.map(t=>`<article class="task-row"><div><b>${esc(t.title)}</b><p>${esc(t.description)}</p></div>${wbButton('跳转','home-jump',`data-type="${t.type}" data-id="${t.id}" ${t.attrs}`)}</article>`).join('')||'<div class="queue-empty">暂时没有待处理事项 ✓</div>'}</div></section>`).join('')}</div>`+wbStoryBoard();
}
function wbCatPage(){
 const titles={cats:['猫咪档案','查看一只猫的照片、现状和各段经历。','新增猫咪'],rescue:['救助记录','先记地点、照片和情况，猫咪档案可以后补。','新增救助'],foster:['寄养记录','保留每一段寄养地点与照护交接。','新增寄养'],adoption:['领养记录','待领养及推进中的猫，与已领养的猫分开查看。','新增领养经历'],sterilization:['绝育记录','按待绝育、住院中和已放归分类；住院中即计入本月工作。','登记绝育']};
 const [title,sub,add]=titles[page];let selectors='';
 if(page==='cats')selectors=tabs(['全部','已领养','已去喵星'].map(s=>[s,s]),wbBusinessTab.cats,'data-wb-state');
 if(page==='sterilization')selectors=tabs(wbStatuses.sterilization.map(s=>[s,s]),wbBusinessTab.sterilization,'data-wb-state');
 if(page==='rescue'||page==='foster')selectors=tabs(['全部',...wbStatuses[page]].map(s=>[s,s]),wbBusinessTab[page],'data-wb-state');
 if(page==='adoption')selectors=tabs([['推进中','待领养 / 推进中'],['已领养','已领养']],wbBusinessTab.adoption,'data-wb-state')+(wbBusinessTab.adoption==='已领养'?`<label class="inline-check"><input type="checkbox" id="wb-adopt-history" ${wbHistoryAdoptions?'checked':''}>包括已退养的历史经历</label>`:'');
 return wbSubnav()+wbTop(title,sub,add)+selectors+(page==='adoption'?(wbBusinessTab.adoption==='已领养'?tabs([['待回访','待回访'],['已回访','已回访']],wbFollowupTab,'data-wb-follow-state'):tabs([['全部','全部'],['有意向领养人','有意向领养人'],['无领养人','无领养人']],wbAdoptionIntent,'data-wb-adopt-intent')):'')+wbFilters(page==='sterilization'&&wbBusinessTab.sterilization==='已放归')+'<div id="wb-list"></div>';
}
function wbBusinessRows(){return active(page).filter(r=>{
 if(!matches(r))return false;
 const t=wbBusinessTab[page];
 if(page==='sterilization')return r.status===t&&(t!=='已放归'||String(r.releaseDate||'').startsWith(month));
 if(page==='adoption')return t==='已领养'?(r.status==='已领养'&&(wbFollowupTab==='已回访'?wbFollowup(r).label==='已完成':wbFollowup(r).label==='待回访')||wbHistoryAdoptions&&r.status==='已退养'&&wbFollowupTab==='已回访'):['无领养人','有意向领养人'].includes(r.status)&&(wbAdoptionIntent==='全部'||r.status===wbAdoptionIntent);
 return t==='全部'||r.status===t;
 });}
function wbBusinessTable(rows){
 if(page==='rescue')return wbTable(['猫咪 / 地点','情况及下一步','医院','状态 / 结果','负责人','操作'],rows.map(r=>[catCell(r.cat||'未建档')+`<div class="date">${esc(r.place)}</div>`,`<button type="button" class="copy-preview rescue-notes-preview" data-action="wb-rescue-notes" data-id="${r.id}" aria-label="查看和修改情况及下一步"><span>${esc((r.issue||'点击填写发现情况')+(r.nextStep?'\n下一步：'+r.nextStep:''))}</span><small>点击查看完整内容</small></button>`,esc(r.hospital||(r.status==='就医中'?'医院待补充':'—')),wbStateButton(page,r)+(r.outcome?`<div class="date">${esc(r.outcome)}</div>`:''),person(r.owner),wbRowActions(page,r)]));
 if(page==='sterilization')return wbTable(['猫咪','抓捕人','手术日期 / 医院','费用','状态','操作'],rows.map(r=>[catCell(r.cat),person(r.capturer),esc(r.surgeryDate||(r.status==='待绝育'?'待安排':'未记录日期'))+`<div class="date">${esc(r.hospital||'医院待补充')}</div>`,money(Math.round(r.cost*100)),wbStateButton(page,r),wbRowActions(page,r)]));
 if(page==='foster')return wbTable(['猫咪','当前地点 / 照护人','状态 / 去向','寄养经历','操作'],rows.map(r=>[catCell(r.cat||'未建档'),esc(r.status==='待安置'?'待确认':r.place||'待确认')+`<div class="date">${esc(r.caregiver||'照护人待补充')}</div>`,wbStateButton(page,r)+`<div class="date">${esc(r.outcome||'')}</div>`,`${r.segments.length} 段记录`,wbRowActions(page,r)]));
 return wbAdoptionTable(rows);
}
function wbInventoryPage(){
 const creative=inventoryGroup==='文创';
 let nav=tabs([['日常','日常物资'],['文创','文创物资']],inventoryGroup,'data-group');
 if(creative){if(!['stock','sales'].includes(inventoryView))inventoryView='stock';nav+=tabs([['stock','库存'],['sales','售卖']],inventoryView,'data-stock-view');if(inventoryView==='sales')nav+=tabs([['线上','线上订单'],['线下','线下活动']],wbSaleChannel,'data-wb-channel');}
 else{if(inventoryView==='sales')inventoryView='stock';nav+=tabs([['stock','库存'],['loans','器材借还'],['movements','变动记录']],inventoryView,'data-stock-view');}
 const sales=creative&&inventoryView==='sales';
 return wbTop('物资管理',sales?(wbSaleChannel==='线上'?'下单占用数量，整单发货或自提交付后扣库存。':'按每场活动登记各款销量和实际总收入。'):'日常用品与文创分开管理，数量变化有记录。',sales?(wbSaleChannel==='线上'?'登记线上订单':'登记线下活动'):(inventoryView==='loans'?'新增借用记录':creative?'新增文创物资':'新增日常物资'))+nav+wbFilters()+'<div id="wb-list"></div>';
}
function wbStockRows(){return active('inventory').filter(r=>r.group===inventoryGroup&&matches(r))}
function wbStockKey(r){return JSON.stringify([r.group,r.name,r.variant||'',r.kind,r.unit])}
function wbStockGroups(rows){const groups=new Map();for(const r of rows){const key=wbStockKey(r);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r)}return [...groups.values()]}
function wbStockTable(rows,paginate=false){return `<div class="stock-groups">${(paginate?wbPageRows(wbStockGroups(rows),6):wbStockGroups(rows)).map(items=>{const r=items[0],creative=r.group==='文创',gear=r.kind==='可借用器材',sum=k=>items.reduce((n,i)=>n+Number(i[k]||0),0),updated=wbStockUpdatedAt(items),heads=creative?['存放地点','在库','待发货 / 待自提','其他预留 / 可售','最后更新','操作']:['存放地点','在库数量',...(gear?['借出中']:[]),'最后更新','操作'];return `<details class="stock-group"><summary><span class="stock-group-name"><b>${esc(r.name)}</b><small>${esc(r.variant||r.kind)}</small></span><span class="stock-group-totals"><b>${sum('qty')} ${esc(r.unit)}</b><small>${items.length} 个存放点${creative?' · 可售 '+items.reduce((n,i)=>n+wbAvailable(data,i.id),0):''}</small></span><span class="stock-group-updated"><small>最后更新</small><time>${esc(wbFormatUpdated(updated))}</time></span><span class="stock-expand-chevron">⌄</span></summary><div class="location-stock">${wbTable(heads,items.map(i=>{const a=wbReservations(data,i.id),loans=active('loans').filter(l=>l.itemId===i.id&&!l.returnedDate).reduce((n,l)=>n+l.quantity,0),actions=wbButton('库存操作','item',`data-id="${i.id}"`)+button('编辑','edit',`data-type="inventory" data-id="${i.id}"`)+button('删除','delete',`data-type="inventory" data-id="${i.id}"`);return creative?[esc(i.place),i.qty+' '+esc(i.unit),a.shipping+' / '+a.pickup,(i.reserved||0)+' / '+wbAvailable(data,i.id),esc(wbFormatUpdated(i.updatedAt)),actions]:[esc(i.place),i.qty+' '+esc(i.unit),...(gear?[loans+' '+esc(i.unit)]:[]),esc(wbFormatUpdated(i.updatedAt)),actions];}))}${wbButton('＋ 添加存放地点','location-add',`data-id="${r.id}"`)}</div></details>`}).join('')||'<div class="empty">这里暂时没有物资。</div>'}</div>`}

function wbSaleStatus(s){return s.cancelledAt?'已取消':s.channel==='线下'?'现场交付':s.delivery==='自提'?(s.deliveredDate?'已自提':'待自提'):(s.deliveredDate?'已发货':'未发货')}
function wbSalesTable(rows){return wbTable(['订单或活动 / 日期','商品及数量','金额 / 收入确认','交付','操作'],rows.map(s=>{
 const b=data.finance.find(b=>b.saleId===s.id),ops=[wbButton('查看','detail',`data-type="sales" data-id="${s.id}"`)];
 if(s.channel==='线上'&&!s.cancelledAt&&!s.deliveredDate)ops.push(wbMenu([wbButton(s.delivery==='自提'?'登记已自提':'登记发货','deliver',`data-id="${s.id}"`),wbButton('编辑','sale-edit',`data-id="${s.id}"`),wbButton('取消订单','cancel-sale',`data-id="${s.id}"`)]));
 return [`<strong class="record-main-title">${esc(s.title)}</strong><div class="date">${esc(s.date)}</div>`,`<span class="wrap">${s.lines.map(l=>esc(l.name)+' × '+l.quantity).join('<br>')}</span>`,money(s.amountCents)+`<div class="date">${badge(b?.status||'待确认')}</div>`,badge(wbSaleStatus(s)),ops.join('')];}));}
