function wbMonthlyPage(){return wbTop('本月工作','完成后自动归档，按实际完成日期查看；线上销售每月汇总，线下每场活动一条。','补充已完成工作')+wbFilters(true)+`<div id="wb-month-categories"></div><div id="wb-month-summary"></div><div id="wb-list"></div>`}
function wbRefresh(){
 if(!$('#wb-list'))return;
 if(page==='monthly'&&wbMonthlyCategory!=='全部'&&!active('monthly').some(r=>r.date.startsWith(month)&&r.category===wbMonthlyCategory))wbMonthlyCategory='全部';
 const remote=window.DanmiaoBackend?.getList(wbListRequest());wbRemoteList=remote&&!remote.loading&&!remote.error?remote:null;
 if(remote?.loading){$('#wb-list').innerHTML='<div class="empty" role="status">正在加载记录…</div>';$('#count').textContent='';return;}
 if(remote?.error){$('#wb-list').innerHTML='<div class="empty" role="alert">'+esc(remote.error)+'<br><button type="button" class="button secondary" id="retry-server-list">重新加载</button></div>';document.querySelector('#retry-server-list').onclick=()=>{window.DanmiaoBackend.clearLists();wbRefresh();};return;}
 let rows=[],html='';wbListPageInfo=null;

 if(page==='cats'){
  rows=wbRemoteList?wbRemoteList.records:active('cats').filter(c=>matches(c)&&(wbBusinessTab.cats==='全部'||DanmiaoDomain.catCategory(data,c)===wbBusinessTab.cats));html=`<div class="cat-grid">${wbPageRows(rows,9).map(c=>`<article class="cat-card" tabindex="0" data-cat-card="${c.id}" aria-label="查看${esc(c.name)}档案"><div class="cat-photo-area"><button type="button" class="cat-portrait portrait-edit portrait-view" data-action="wb-detail" data-type="cats" data-id="${c.id}" aria-label="查看${esc(c.name)}详情">${c.avatar?`<img data-asset="${esc(c.avatar.id)}" alt="${esc(c.name)}的头像">`:wbCatFace(c)}</button></div><div class="cat-card-body"><div class="cat-card-title"><h3>${esc(c.name)}${DanmiaoDomain.catCategory(data,c)!=='其他'?` <span class="badge">${esc(DanmiaoDomain.catCategory(data,c))}</span>`:''}</h3>${wbButton('更换头像','avatar',`data-id="${c.id}" aria-label="更换${esc(c.name)}头像"`)}</div><p>${esc([c.place,c.health].filter(Boolean).join(' · ')||'基本资料待补充')}</p>${wbButton('查看档案与经历','detail',`data-type="cats" data-id="${c.id}"`)}</div></article>`).join('')}</div>`;
 }else if(businessTypes.includes(page)){rows=wbRemoteList?wbRemoteList.records:wbBusinessRows();html=wbBusinessTable(wbPageRows(rows));}
 else if(page==='inventory'){
  if(inventoryView==='stock'){rows=wbRemoteList?wbRemoteList.records:wbStockRows();html=wbStockTable(rows,true);}
  else if(inventoryView==='sales'){rows=wbRemoteList?wbRemoteList.records:active('sales').filter(s=>s.channel===wbSaleChannel&&matches(s));html=wbSalesTable(wbPageRows(rows));}
  else if(inventoryView==='loans'){rows=wbRemoteList?wbRemoteList.records:active('loans').filter(matches);html=wbLoanTable(wbPageRows(rows));}
  else{rows=wbRemoteList?wbRemoteList.records:active('movements').filter(r=>(!r.itemId||find('inventory',r.itemId)?.group===inventoryGroup)&&matches(r));html=wbTable(['日期','物资','操作 / 数量','经办人','用途（器材）','备注'],wbPageRows(rows).map(r=>[esc(r.date),esc(r.itemName),esc(r.type)+' · '+r.quantity,person(r.owner),esc(['借出','归还'].includes(r.type)?r.destination||'—':'—'),`<span class="wrap">${esc(r.note||'')}</span>`]));}
 }else if(page==='finance'){
  rows=wbRemoteList?wbRemoteList.records:active('finance').filter(b=>matches(b)&&(wbFinanceTab==='待结清'?wbIsPendingSettlement(b):wbFinanceTab==='收入待确认'?b.flow==='收入'&&(b.status==='待确认'||b.refundReview):wbFinanceTab==='报销待审核'?b.flow==='个人垫付'&&b.status==='待审核':wbFinanceTab==='待处理'?['待确认','待审核'].includes(b.status)||b.refundReview:b.date.startsWith(month))).filter(b=>wbFinanceTab!=='明细'||wbLedgerDirection==='全部'||(wbLedgerDirection==='收入'?b.flow==='收入':b.flow!=='收入'));
  html=wbLedgerTable(wbPageRows(rows));const s=wbFinance(data,month);$('#wb-fin-summary').innerHTML=`<div class="summary-strip"><span>确认收入 <b>${money(s.income)}</b></span><span>待确认 <b>${money(s.unconfirmed)}</b></span><span>本月已发生费用 <b>${money(s.expense)}</b></span><span>待结清 <b>${money(active('finance').filter(wbIsPendingSettlement).reduce((n,b)=>n+b.amountCents,0))}</b></span><span>累计账面结余 <b>${money(s.balance)}</b></span></div>`;
 }else if(page==='monthly'){
  const monthRows=active('monthly').filter(r=>r.date.startsWith(month)),categories=[...new Set(monthRows.map(r=>r.category))];if(wbMonthlyCategory!=='全部'&&!categories.includes(wbMonthlyCategory))wbMonthlyCategory='全部',wbAdoptionIntent='全部',wbFollowupTab='待回访';rows=wbRemoteList?wbRemoteList.records:monthRows.filter(r=>matches(r)&&(wbMonthlyCategory==='全部'||r.category===wbMonthlyCategory)).sort((a,b)=>b.date.localeCompare(a.date));const countBy={};for(const r of monthRows)countBy[r.category]=(countBy[r.category]||0)+1;
  $('#wb-month-categories').innerHTML=tabs([['全部','全部类型'],...categories.map(t=>[t,t])],wbMonthlyCategory,'data-wb-month-type');
  $('#wb-month-summary').innerHTML=`<div class="summary-strip"><b>${monthRows.length} 项完成工作</b>${wbMonthlyCountText(monthRows).map(text=>`<span>${esc(text)}</span>`).join('')}${wbMonthlyCategory!=='全部'?`<span class="month-filter-count">当前筛选 ${wbRemoteList?wbRemoteList.total:rows.length} 项</span>`:''}</div>`;
  html=wbTable(['工作 / 完成日期','类型','工作成果','来源','操作'],wbPageRows(rows).map(r=>[`<strong class="record-main-title">${esc(r.title)}</strong><div class="date">${esc(r.date)}</div>`,badge(r.category),`<span class="wrap">${esc(r.result)}</span>`,r.sourceType&&r.sourceType!=='sales'?wbButton('查看原记录','home-jump',`data-type="${r.sourceType}" data-id="${r.sourceId}"`):r.sourceType==='sales'?'售卖汇总':'手动补充',wbButton('补充说明','monthly-edit',`data-id="${r.id}"`)]));
 }
 $('#wb-list').innerHTML=html+wbPagination();$('#count').textContent=wbRemoteList?(wbRemoteList.grouped?'共 '+wbRemoteList.total+' 种物资 · '+wbRemoteList.recordTotal+' 条地点库存':'共 '+wbRemoteList.total+' 条'):page==='inventory'&&inventoryView==='stock'?'共 '+wbStockGroups(rows).length+' 种物资 · '+rows.length+' 条地点库存':'共 '+rows.length+' 条';wbLoadImages();wbUpdateCopyHints();wbFocusHomeTarget();
}
function wbEditBusiness(type,id){
 const r=find(type,id)||{},catField=wbBusinessCatField(type,r);
 let fields=catField;
 if(type==='rescue')fields+=field('发现地点','place',r.place)+field('发现情况','issue',r.issue,'textarea')+field('救助状态','status',r.status||'待救助','text',wbStatuses.rescue)+wbWhenStatus(wbHospitalField(r),['就医中'])+wbWhenStatus(optional(field('结束后的结果','outcome',r.outcome||'','text',['','去喵星','放归','转寄养']))+optional(field('结束日期（已结束时填写）','completedDate',r.completedDate||'','date')),['已结束']);
 if(type==='sterilization')fields+=optional(field('抓捕人（可留空）','capturer',r.capturer||''))+field('状态','status',r.status||'待绝育','text',wbStatuses.sterilization)+wbWhenStatus(field('手术日期','surgeryDate',r.surgeryDate||today,'date'),['住院中'])+wbWhenStatus(wbHospitalField(r),['住院中','已放归'])+optional(field('费用（元）','cost',r.cost||'','number').replace('step="1"','step="0.01"'))+wbWhenStatus(field('放归日期','releaseDate',r.releaseDate||today,'date')+field('放归地点','releasePlace',r.releasePlace||''),['已放归']);
 if(type==='foster')fields+=field('寄养状态','status',r.status||'待安置','text',wbStatuses.foster)+optional(field('当前寄养地点（入住时必填）','place',r.place||''))+optional(field('实际照护人（入住时必填）','caregiver',r.caregiver||''))+field('本段入住日期','date',r.date||today,'date')+optional(field('寄养结束去向','outcome',r.outcome||'','text',['','已领养','已放归']))+optional(field('结束日期','completedDate',r.completedDate||'','date'))+field('照护及交接备注','note',r.note||'','textarea');
 if(type==='adoption')fields+=wbAdoptionFields(r)+optional(field('意向人 / 领养人称呼','applicant',r.applicant||''))+field('领养进度','status',r.status||'无领养人','text',wbStatuses.adoption)+wbWhenStatus(optional(field('实际领养日期','adoptDate',r.adoptDate||'','date'))+field('第一个月回访间隔（天）','earlyInterval',r.earlyInterval||7,'number')+field('满一个月后间隔（天）','regularInterval',r.regularInterval||30,'number'),['已领养'])+field('备注','note',r.note||'','textarea');
 if(type!=='sterilization')fields+=optional(field('负责人（可留空）','owner',r.owner||''));
 fields+=`<details class="advanced"><summary>补充下一步与说明</summary>${optional(field('下一步（可留空）','nextStep',r.nextStep||''))}</details><p class="form-hint">保存记录后，可以在详情添加照片${type==='adoption'?'和协议文件':''}。</p>`;
 showModal((id?'编辑':'新增')+wbTitle[type],fields,values=>wbSubmitBusiness(type,values,id));wbFormVisibility();wbBusinessCatVisibility();
}
function wbBusinessCatField(type,r){const existing=wbFindCat(r.cat),value=existing?.name||(r.cat?'__new__':'');return optional(field('选择猫咪档案','catPick',value,'text',[{value:'',label:type==='rescue'?'暂不关联猫咪':'请选择猫咪'},...active('cats').map(c=>({value:c.name,label:[c.name,c.coatType,c.place].filter(Boolean).join(' · ')})),{value:'__new__',label:'＋ 填写新猫咪 / 临时称呼'}])).replace('<select name="catPick"','<select name="catPick" '+(type==='rescue'?'':'required '))+`<div data-new-cat>${type==='rescue'?optional(field('猫咪名称或临时称呼（可后补）','cat',r.cat||'')):field('猫咪名称或临时称呼','cat',r.cat||'')}</div>`;}
function wbBusinessCatVisibility(changed=false){const select=document.querySelector('select[name=catPick]'),input=document.querySelector('input[name=cat]'),wrap=document.querySelector('[data-new-cat]');if(!select?.options||!input||!wrap)return;const custom=select.value==='__new__';wrap.hidden=!custom;if(custom&&changed)input.value='';input.required=custom&&select.required;if(!custom)input.value=select.value;const c=!custom&&wbFindCat(select.value);if(c)for(const key of ['sex','age','coatType','neuterStatus','medicalHistory']){const field=document.querySelector('#fields [name="'+key+'"]');if(field){field.value=c[key]||'';field.dispatchEvent(new Event('change',{bubbles:true}));}}}
